<?php $rows=$pdo->query("SELECT l.*,b.full_name borrower,e.name equipment,i.asset_code,u.full_name issuer FROM loans l JOIN borrowers b ON b.id=l.borrower_id JOIN equipment_items i ON i.id=l.item_id JOIN equipment e ON e.id=i.equipment_id JOIN users u ON u.id=l.issued_by WHERE l.returned_at IS NULL ORDER BY l.due_date")->fetchAll();layout_start('Active loans','loans'); ?><div class="page-heading"><div><p class="eyebrow">LOAN MANAGEMENT</p><h1>Active loans</h1><p class="muted">Equipment currently checked out to borrowers.</p></div></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Borrower</th><th>Equipment</th><th>Issued</th><th>Due date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$late=$r['due_date']<date('Y-m-d'); ?><tr><td><a class="text-link" href="?page=borrower-view&id=<?=$r['borrower_id']?>"><?=h($r['borrower'])?></a></td><td><?=h($r['equipment'])?><small class="cell-sub"><?=h($r['asset_code'])?></small></td><td><?=date('j M Y',strtotime($r['issued_at']))?></td><td><?=date('j M Y',strtotime($r['due_date']))?></td><td><span class="badge <?=$late?'overdue':'on-loan'?>"><?=$late?'Overdue':'On Loan'?></span></td><td><a class="button small secondary" href="?page=return&id=<?=$r['id']?>">Process return</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="table-empty">No active loans. Issued equipment will appear here.</div><?php endif; ?></div></section><?php layout_end();
